let accountChallenge='';
workspaceLogin=function(){return `<section class="card prose"><h2>${workspaceSession?'Your account':'Sign in to Scholarion Academy'}</h2><p id="account-status" role="status"></p>${workspaceSession?`<p>${esc(workspaceSession.user)} · ${esc(workspaceSession.accountType||workspaceSession.role)}</p><button class="button" id="workspace-signout">Sign out</button>${workspaceSession.accountType==='super_admin'?`<h3>Account administration</h3><form data-account="invite"><label>Account type<select name="kind"><option value="student">Student</option><option value="employee">Employee</option><option value="super_admin">Super Admin</option></select></label><button class="button">Create one-time invitation</button></form><form data-account="enroll"><label>Username<input name="username" required></label><label>Course code<input name="course" required></label><button class="button">Assign course access</button></form><button class="button secondary" id="account-list">Show accounts</button><div id="account-users"></div>`:''}`:`<form data-account="login"><label>Username<input name="username" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button class="button">Continue</button></form><details><summary>Create your account</summary><form data-account="register"><label>Username<input name="username" minlength="3" maxlength="64" autocomplete="username" required></label><label>Password (at least 12 characters)<input name="password" type="password" minlength="12" maxlength="128" autocomplete="new-password" required></label><label>Invitation code (employees and administrators)<input name="invite" autocomplete="off"></label><p>Without an invitation, a student account is created. Course access is assigned separately.</p><button class="button">Create account and set up 2FA</button></form></details><details><summary>First Super Admin setup</summary><p>The one-time setup code is in the server's private account-bootstrap.txt file. Setup is disabled after the first administrator is created.</p><form data-account="bootstrap"><label>Setup code<input name="setupCode" type="password" required></label><label>Username<input name="username" required autocomplete="username"></label><label>Password<input name="password" type="password" minlength="12" maxlength="128" required autocomplete="new-password"></label><button class="button">Set up Super Admin</button></form></details><div id="account-mfa"></div>`}</section>`;};
document.addEventListener('submit',async e=>{const action=e.target.dataset.account;if(!action)return;e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{governedToken='';const d=Object.fromEntries(new FormData(e.target));const r=await workspaceApi('accounts/'+action,d);if(r.error)throw Error(r.error);e.target.reset();if(r.challenge){accountChallenge=r.challenge;document.getElementById('account-mfa').innerHTML=`<h3>Two-factor authentication</h3>${r.setupSecret?`<p>Add a time-based account in your authenticator app using this setup key. Keep it private.</p><code>${esc(r.setupSecret)}</code>`:''}<form data-account="verify"><input type="hidden" name="challenge" value="${esc(accountChallenge)}"><label>6-digit authenticator code<input name="code" inputmode="numeric" pattern="[0-9]{6}" autocomplete="one-time-code" required></label><button class="button">Verify and sign in</button></form>`;}else if(action==='verify'){accountChallenge='';document.getElementById('account-mfa').innerHTML='';location.hash='#workspace-session';render();}else document.getElementById('account-status').textContent=r.invite?'One-time invitation (expires in 24 hours): '+r.invite:'Saved.';}catch(err){document.getElementById('account-status').textContent=err.message;}finally{button.disabled=false;}});
document.addEventListener('click',async e=>{if(e.target.id!=='account-list')return;try{const r=await workspaceApi('accounts/list');document.getElementById('account-users').innerHTML=r.accounts.map(a=>`<p>${esc(a.username)} · ${esc(a.kind)} · ${a.active?'2FA active':'2FA setup pending'}</p>`).join('');}catch(err){document.getElementById('account-status').textContent=err.message;}});
const previousWorkspaceFrame=workspaceFrame;
workspaceFrame=function(route,body){previousWorkspaceFrame(route,body);if(workspaceSession&&selectedCourse&&['courses','assignments','server-coursework','grades'].includes(route))document.querySelector('main')?.insertAdjacentHTML('afterbegin','<p><a class="button" href="#classroom">Join live lecture · Zoom / Webex</a></p>');};
workspaceRoutes.classroom='Live classroom';
const previousAccountRender=render;
render=function(){if(location.hash==='#signin'){location.hash='#workspace-session';return;}if(location.hash!=='#classroom')return previousAccountRender();classroomRender();};
async function classroomRender(){try{workspaceSession=await workspaceApi('session');if(!workspaceSession.courses.includes(selectedCourse))selectedCourse=workspaceSession.courses[0]||'';if(!selectedCourse){workspaceFrame('classroom','<p>No course access assigned yet.</p>');return;}const r=await workspaceApi('classroom-meetings/list');workspaceFrame('classroom',`<section class="card prose"><h2>${esc(selectedCourse)} · Live lectures and instructor meetings</h2><p id="meeting-status" role="status"></p>${r.meetings.length?r.meetings.map(m=>`<article><h3>${esc(m.title)}</h3><p>${esc(new Date(m.starts).toLocaleString())}</p><a class="button" href="${esc(m.url)}" target="_blank" rel="noopener noreferrer">Join ${m.provider==='zoom'?'Zoom':'Webex'}</a>${r.role==='instructor'?` <button class="button secondary" data-remove-meeting="${esc(m.id)}">Remove link</button>`:''}</article>`).join(''):'<p>Your instructor has not posted a live meeting yet.</p>'}${r.role==='instructor'?`<h3>Add a lecture or meeting</h3><form id="classroom-add"><label>Title<input name="title" maxlength="150" required></label><label>Provider<select name="provider"><option value="zoom">Zoom</option><option value="webex">Webex</option></select></label><label>Start time<input name="starts" type="datetime-local" required></label><label>Meeting join URL<input name="url" type="url" required></label><button class="button">Post meeting link</button></form>`:''}</section>`);}catch(e){workspaceSession=null;workspaceFrame('classroom','<section class="card prose"><h2>Live lectures and instructor meetings</h2><p>Zoom and Webex join links appear here for your enrolled courses.</p></section>');}}
document.addEventListener('submit',async e=>{if(e.target.id!=='classroom-add')return;e.preventDefault();try{const d=Object.fromEntries(new FormData(e.target));d.starts=new Date(d.starts).toISOString();await workspaceApi('classroom-meetings/add',d);await classroomRender();}catch(err){document.getElementById('meeting-status').textContent=err.message;}});
document.addEventListener('click',async e=>{const id=e.target.dataset.removeMeeting;if(!id)return;try{await workspaceApi('classroom-meetings/remove',{id});await classroomRender();}catch(err){document.getElementById('meeting-status').textContent=err.message;}});
render();
